auto grid = std::make_shared<NeoWPF::UI::Grid>();
auto button = std::make_shared<NeoWPF::Button>(L"OK");
grid->AddRow(NeoWPF::UI::SizeMode::Auto, 0);
grid->AddColumn(NeoWPF::UI::SizeMode::Star, 1);
grid->AddChild(button, 0, 0);

auto slider = std::make_shared<NeoWPF::UI::Slider>();
slider->SetMinimum(0.0);
slider->SetMaximum(100.0);
slider->SetValue(50.0);
slider->ValueChanged += [](double value) {
// Respond to the selected value.
};

auto tb = std::make_shared<NeoWPF::UI::TextBox>();
tb->SetText(L"Hello world");
tb->SetFontSize(14);
tb->SetPadding(6);
// register a handler function: avoid inlined block comments inside the example
tb->TextChanged += OnTextChanged;
